//! Rescyo's desktop interface: Slint with the software renderer, so it looks the same on every
//! platform, down to Windows 7, remote desktops and live-USB systems, and follows docs/design.
//!
//! Our code contains no `unsafe` (`deny` from the workspace). The exceptions are the code the
//! Slint compiler generates from `ui/*.slint` ([`generated`]) and the window-material calls of
//! [`platform`], each confined to its module.
#![deny(unsafe_code)]

mod controller;
mod fonts;
pub mod platform;
mod strings;

mod generated {
    #![allow(unsafe_code, reason = "code generated by the Slint compiler")]
    #![allow(
        clippy::all,
        clippy::pedantic,
        clippy::restriction,
        clippy::nursery,
        missing_debug_implementations,
        reason = "generated code"
    )]
    slint::include_modules!();
}

pub use generated::*;

use std::path::PathBuf;

use slint::ComponentHandle;

/// Options from the command line.
#[derive(Debug, Clone, Default)]
pub struct Options {
    pub lang: Option<String>,
    /// A session to open at start.
    pub session: Option<PathBuf>,
    /// Force a theme instead of following the system.
    pub dark: Option<bool>,
}

/// Opens the main window and runs until it is closed.
pub fn run(opts: Options) -> Result<(), slint::PlatformError> {
    platform::select_backend();
    let ui = MainWindow::new()?;
    platform::prepare(&ui);
    if let Some(dark) = opts.dark {
        ui.global::<Tokens>().set_dark(dark);
    } else {
        ui.global::<Tokens>().set_dark(platform::prefers_dark());
    }
    let l = rescyo_i18n::Localizer::new(opts.lang.as_deref());
    fonts::load_cjk(l.lang());
    let c = controller::Controller::new(&ui, l);
    controller::CONTROLLER.with(|slot| *slot.borrow_mut() = Some(c.clone()));
    c.load_sources();
    if let Some(s) = &opts.session {
        c.open_session(s);
    }
    ui.window().set_size(slint::LogicalSize::new(1360.0, 820.0));
    ui.show()?;
    // The native window exists only once the event loop runs: dress it on the first ticks.
    let weak = ui.as_weak();
    let tries = std::rc::Rc::new(std::cell::Cell::new(0u32));
    let timer = slint::Timer::default();
    timer.start(
        slint::TimerMode::Repeated,
        std::time::Duration::from_millis(16),
        move || {
            let Some(ui) = weak.upgrade() else { return };
            tries.set(tries.get() + 1);
            if platform::dress(&ui) || tries.get() > 60 {
                tries.set(u32::MAX / 2);
            }
        },
    );
    slint::run_event_loop()?;
    drop(timer);
    ui.hide()
}

